-- Généré par tests/build_guide.lua depuis GUIDE.ptBR.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.ptBR = {
    { "h1", "Guia do Panorama" },
    { "p", "Como usar o Panorama no WoW Forever e como configurar o HDR no Windows." },
    { "p", "|cffffd100Faça antes um backup das suas configurações.|r O Panorama altera configurações do jogo, e remover o addon não as desfaz. Antes de mudar qualquer coisa, feche o jogo e copie a pasta |cffffd100WTF|r da sua instalação do jogo para um lugar seguro. Para voltar atrás, feche o jogo e coloque essa cópia de volta no lugar." },
    { "h2", "1. Abrir a janela" },
    { "li", "Digite |cffffd100/pano|r, ou clique com o botão esquerdo no botão do Panorama no minimapa.", "-" },
    { "li", "Opções > AddOns > Panorama também tem um botão que a abre.", "-" },
    { "li", "Arraste a barra de título para mover a janela. Esc ou o botão de fechar a fecha.", "-" },
    { "p", "O botão do minimapa:" },
    { "li", "Clique esquerdo abre ou fecha a janela.", "-" },
    { "li", "Clique direito mostra as predefinições, o desfazer, o refazer e a reinicialização gráfica.", "-" },
    { "li", "Arraste-o para movê-lo ao redor do minimapa. |cffffd100/pano minimap|r o mostra ou oculta.", "-" },
    { "h2", "2. A janela" },
    { "row", "Caixa de busca (canto superior direito)", "Digite uma palavra para listar as configurações correspondentes de todas as abas. Limpe-a para voltar." },
    { "row", "Abas", "Qualidade, Interface, Avançado (configurações do jogo), depois Filtros, Meus filtros, Ambiente (efeitos do Panorama). A aba aberta é lembrada." },
    { "row", "Configurações avançadas (sob o título)", "Desmarcada: sem abas, uma única página com as predefinições, as principais configurações de qualidade (distância de visão, neblina volumétrica, sombras, oclusão de ambiente, detalhe da água, antisserrilhamento, atenuação da nitidez), a saída HDR e o brilho de pico, o contraste, o brilho, a distância da câmera, o filtro, a intensidade do filtro e o modo de ambiente. Marcada: todas as abas e todas as configurações. Na primeira instalação fica desmarcada; se você já usava o Panorama, fica marcada. A busca sempre encontra todas as configurações." },
    { "row", "Desfazer, Refazer (sob as abas, à direita)", "Desfazer cancela sua última alteração: controle deslizante, caixa, predefinição, filtro, ambiente ou Redefinir tudo. Refazer a recoloca. As últimas 20 alterações ficam guardadas até |cffffd100/reload|r." },
    { "row", "Seletor de idioma (à direita das abas)", "Idioma do jogo ou um de dez idiomas. Mudar o idioma recarrega a interface." },
    { "row", "Guia (à esquerda da caixa de busca)", "Abre este guia no jogo." },
    { "row", "Predefinições (aba Qualidade)", "Baixa, Média, Alta, Extra. A predefinição que combina com suas configurações fica destacada." },
    { "row", "Rodapé", "Aplicar a cada conexão, botão do minimapa, Redefinir tudo, reinicialização do motor gráfico." },
    { "p", "Clique no título de uma seção para recolhê-la ou expandi-la." },
    { "h3", "Uma linha de configuração" },
    { "li", "|cffffd100Controle deslizante|r: o valor é gravado quando você solta o botão do mouse, não enquanto arrasta.", "-" },
    { "li", "|cffffd100Caixa de valor|r ao lado do controle: digite um valor, depois pressione Enter ou clique em outro lugar. Esc cancela, Tab vai para a próxima caixa. A vírgula funciona como separador decimal. O valor fica dentro do intervalo do controle.", "-" },
    { "li", "|cffffd100Botão Padrão|r: devolve essa configuração ao valor padrão. Passe o mouse sobre ele para ver o valor.", "-" },
    { "li", "|cffffd100Marca dourada|r à esquerda: você mudou essa configuração.", "-" },
    { "li", "|cffffd100Estrela amarela|r: um menu do jogo também define esse valor. Passe o mouse sobre ela para ver qual. Esse menu não lê o valor de volta, então pode mostrar outro nível.", "-" },
    { "li", "|cffffd100Linha acinzentada|r: depende de outra configuração que está desligada (por exemplo, a densidade da névoa sem névoa volumétrica, a intensidade da tonalidade sem tonalidade). A linha indica qual configuração mudar.", "-" },
    { "li", "Passe o mouse sobre um rótulo para ler a ajuda completa.", "-" },
    { "h2", "3. Predefinições" },
    { "row", "Baixa", "Desempenho máximo. Visão curta, sem sombras." },
    { "row", "Média", "Equilibrado. Bom desempenho e sombras razoáveis." },
    { "row", "Alta", "Nível Alto do jogo. Sombras completas, todos os efeitos." },
    { "row", "Extra", "Qualidade máxima. Maior distância de visão, tudo ligado." },
    { "p", "As predefinições mudam apenas as configurações de qualidade gráfica da aba Qualidade. Elas não mexem na câmera, no mouse, na interface, na nitidez, na baixa latência, no HDR nem nos filtros." },
    { "p", "Mudou de ideia? |cffffd100Desfazer|r (sob as abas, ou |cffffd100/pano undo|r) restaura as configurações de antes da predefinição." },
    { "h2", "4. Filtros" },
    { "p", "A aba Filtros adiciona efeitos sobre a imagem. Eles não mudam nenhuma configuração do jogo." },
    { "li", "|cffffd100Tonalidade|r: clique em uma miniatura para aplicá-la na hora (sépia, quente, fria, noite, esmeralda, crepúsculo). |cffffd100Intensidade da tonalidade|r define a força.", "-" },
    { "li", "|cffffd100Meu filtro|r: usa um dos seus filtros da aba Meus filtros. Ele substitui a tonalidade, a vinheta e a granulação.", "-" },
    { "li", "|cffffd100Céu|r: as mesmas cores em gradiente, cheias no alto da tela e mais claras embaixo. |cffffd100Intensidade do céu|r define a força.", "-" },
    { "li", "|cffffd100Vinheta|r: escurece as bordas da tela.", "-" },
    { "li", "|cffffd100Granulação|r: granulação animada.", "-" },
    { "li", "|cffffd100Barras pretas|r: barras em cima e embaixo, de 0 a 20 % da tela cada uma. O jogo ainda renderiza o que elas escondem, então não aumentam a taxa de quadros.", "-" },
    { "h3", "Ambiente" },
    { "p", "A aba Ambiente muda sozinha o tom, o céu, a vinheta e a granulação conforme o lugar onde você está." },
    { "li", "|cffffd100Modo|r (topo da aba): |cffffd100Desligado|r (a aba Filtros vale em toda parte), |cffffd100Dia e noite automáticos|r (veja Dia e noite abaixo) ou |cffffd100Ambiente automático|r. Desligado por padrão.", "-" },
    { "li", "|cffffd100Ambiente automático|r: esses filtros seguem o lugar e a hora do dia. Os valores da aba Filtros continuam salvos e voltam quando você muda o modo. Sem Configurações avançadas, a página única mostra só o modo e o lugar detectado; marque Configurações avançadas para editar os contextos.", "-" },
    { "li", "|cffffd100Lugar|r: define o tom, a vinheta e a granulação. Ordem: masmorra ou raide, interior, clima (chuva, neve, tempestade de areia), depois o tipo de zona: terras temperadas, desertos e terras áridas, terras nevadas, selva e pântano, terras corrompidas, terras vulcânicas, florestas arcanas. Uma zona ainda desconhecida conta como temperada. O clima só conta quando Intensidade do clima é maior que 0.", "-" },
    { "li", "|cffffd100Hora do dia|r: define o céu (dia, amanhecer e entardecer, noite). A noite segue o dia e a noite do jogo; o amanhecer e o entardecer seguem a hora do servidor. Sem céu em interiores nem em masmorras.", "-" },
    { "li", "A linha à direita mostra o lugar e a hora do dia detectados agora. Quando uma masmorra, um interior ou o clima vem antes de uma zona que você ajustou, ela indica isso.", "-" },
    { "li", "|cffffd100Contexto a editar|r: escolha um contexto e ajuste seus filtros abaixo. O botão Padrão devolve o valor fornecido para esse contexto. O menu tem cinco grupos: |cffffd100Zonas|r (a zona em que você está e as que você ajustou), |cffffd100Masmorra e interior|r, |cffffd100Clima|r, |cffffd100Tipo de zona|r e |cffffd100Céu (hora)|r. Os quatro primeiros ajustam o tom, a vinheta, a granulação e uma predefinição gráfica: só um lugar se aplica por vez, na ordem indicada acima. O último ajusta o céu. Não é preciso ajustar nada para começar: cada contexto já tem seus valores.", "-" },
    { "li", "|cffffd100Esta zona|r: primeira opção do mesmo menu, com o nome da zona em que você está. Escolha-a para dar a esta zona seu próprio tom, vinheta e granulação, partindo do seu tipo de zona. Ela passa então antes do tipo de zona, mas depois de masmorra, interior e clima. As zonas que você ajusta continuam no menu. |cffffd100Tipo de zona|r remove os valores da zona: ela volta a seguir seu tipo de zona.", "-" },
    { "li", "|cffffd100Todas as zonas|r: submenu do mesmo menu, com todas as zonas conhecidas. Escolha uma para ajustá-la sem estar lá. As zonas são organizadas por continente.", "-" },
    { "li", "|cffffd100Predefinição|r e |cffffd100Distância do cenário|r (primeiras linhas de um lugar ou de uma zona): elas se aplicam enquanto você está nesse lugar, por cima dos seus próprios ajustes, com o ambiente automático ligado ou não. A distância do cenário do lugar vem antes da distância da predefinição. Seus próprios ajustes são mantidos e voltam quando você sai. |cffffd100Meus ajustes|r não muda nada. Exemplo: Baixa em masmorras, Extra em uma zona de que você gosta. Em uma masmorra ou raide, a primeira opção do menu ajusta só essa masmorra. Na aba Qualidade, o botão |cffffd100Por lugar|r abre essas linhas para o lugar onde você está; ele mostra |cffffd100Aqui: …|r enquanto um lugar aplica os seus. Em combate, a mudança espera o fim do combate.", "-" },
    { "li", "|cffffd100Meu filtro|r (primeira linha dos filtros de um lugar ou de uma zona): esse lugar usa um dos seus filtros da aba Meus filtros, com o contraste, o brilho e a gama dele, enquanto o ambiente automático estiver ligado.", "-" },
    { "li", "|cffffd100Dia e noite|r (modo |cffffd100Dia e noite automáticos|r): o Panorama aplica a |cffffd100Tonalidade diurna|r de dia e a |cffffd100Tonalidade noturna|r à noite, segundo o dia e a noite do jogo. Elas substituem a tonalidade da aba Filtros. A mudança é gradual das 19h às 21h e das 5h às 7h (horário do servidor). As tonalidades diurna e noturna e suas intensidades são definidas com Configurações avançadas.", "-" },
    { "h2", "5. Meus filtros" },
    { "p", "A aba Meus filtros (visível com Configurações avançadas) serve para criar quantos filtros seus você quiser. |cffffd100Novo|r adiciona um, |cffffd100Excluir|r remove o filtro aberto: a aba Filtros, os lugares e as zonas que o usavam voltam para Nenhum." },
    { "li", "|cffffd100Filtro a editar|r: escolhe o filtro que as linhas abaixo ajustam. |cffffd100Nome|r: dê um nome a ele (Enter para confirmar).", "-" },
    { "li", "|cffffd100Vermelho|r, |cffffd100Verde|r, |cffffd100Azul|r (em %): cor da tonalidade do filtro. |cffffd100Intensidade da tonalidade|r: a força dela.", "-" },
    { "li", "|cffffd100Vinheta|r e |cffffd100Granulação|r: as do filtro.", "-" },
    { "li", "|cffffd100Contraste|r, |cffffd100Brilho|r, |cffffd100Gama|r: ajustes de imagem que o filtro dá ao jogo enquanto está aplicado; depois voltam os seus próprios valores. Meus ajustes: nada muda. Dependendo do modo de exibição, podem não ter efeito.", "-" },
    { "li", "Enquanto a aba está aberta, o filtro exibido aparece ao vivo no jogo.", "-" },
    { "li", "Para usar um filtro: escolha-o na linha |cffffd100Meu filtro|r da aba Filtros (em todo lugar), ou de um lugar ou de uma zona na aba Ambiente (ambiente automático ligado). Ele substitui então a tonalidade, a vinheta e a granulação, cujas linhas ficam acinzentadas. Nenhum: nada muda.", "-" },
    { "h2", "6. Seus valores e o jogo" },
    { "li", "Na primeira instalação, o Panorama lê suas configurações atuais do jogo. Nada muda até você mexer em um controle.", "-" },
    { "li", "Uma mudança feita no menu Gráficos do jogo ou com |cffffd100/console|r aparece na janela.", "-" },
    { "li", "|cffffd100Aplicar a cada conexão|r (rodapé, ligado por padrão): as configurações que você mudou no Panorama são gravadas de novo a cada conexão. As outras seguem o menu Gráficos do jogo.", "-" },
    { "li", "Uma mudança feita durante o combate é aplicada quando o combate termina.", "-" },
    { "li", "Algumas configurações, como o MSAA, exigem a reinicialização gráfica. Clique em |cffffd100Reiniciar|r no rodapé, ou digite |cffffd100/pano restart|r. A tela pisca por um segundo.", "-" },
    { "h2", "7. HDR no Windows" },
    { "p", "As configurações de HDR existem apenas como comandos de console no jogo. O Panorama as mostra na aba |cffffd100Avançado|r, seção |cffffd100HDR (só console)|r. Você precisa de um monitor compatível com HDR." },
    { "h3", "Passo 1: ativar o HDR no Windows" },
    { "p", "Windows 11:" },
    { "li", "Abra |cffffd100Configurações > Sistema > Vídeo|r.", "1." },
    { "li", "Selecione o monitor HDR, se você tiver mais de um.", "2." },
    { "li", "Ative |cffffd100Usar HDR|r. O atalho |cffffd100Win + Alt + B|r também o liga ou desliga.", "3." },
    { "p", "Windows 10: |cffffd100Configurações > Sistema > Vídeo > Configurações de Cores HD do Windows|r (Windows HD Color settings), depois ative |cffffd100Reproduzir jogos e aplicativos em HDR|r (Play HDR games and apps)." },
    { "p", "Verifique também se o HDR está ativado no menu do próprio monitor, se ele tiver essa opção." },
    { "p", "Desative o |cffffd100HDR automático|r (Auto HDR) do Windows 11: |cffffd100Configurações > Sistema > Vídeo > HDR|r. Ele serve para jogos sem HDR. O WoW gera a própria imagem HDR." },
    { "h3", "Passo 2: descobrir o brilho de pico do seu monitor" },
    { "p", "Instale o aplicativo gratuito |cffffd100Calibragem HDR do Windows|r (Windows HDR Calibration) da Microsoft Store e execute-o. A luminância máxima que ele encontra é o brilho de pico do seu monitor, em nits." },
    { "p", "Sem o aplicativo, use a classificação HDR do monitor: DisplayHDR 400 significa cerca de 400 nits, DisplayHDR 600 cerca de 600, DisplayHDR 1000 cerca de 1000." },
    { "h3", "Passo 3: configurar o HDR no Panorama" },
    { "p", "Abra |cffffd100/pano|r, aba |cffffd100Avançado|r, seção |cffffd100HDR (só console)|r." },
    { "li", "Marque |cffffd100Saída HDR|r.", "1." },
    { "li", "Marque |cffffd100Usar brilho de pico|r ou |cffffd100Usar brilho de referência|r: um ou outro, nunca os dois. Sem um deles, a imagem fica escura.", "2." },
    { "p", "|cffffd100Modo de brilho de pico (recomendado)|r" },
    { "li", "Marque |cffffd100Usar brilho de pico|r.", "-" },
    { "li", "Defina |cffffd100Brilho de pico (nits)|r com o valor encontrado no passo 2.", "-" },
    { "li", "|cffffd100Intensidade HDR|r só funciona nesse modo. O padrão do jogo é 2. Mude-o em pequenos passos e compare: a Blizzard não documenta o efeito exato.", "-" },
    { "p", "|cffffd100Modo de brilho de referência|r" },
    { "li", "Marque |cffffd100Usar brilho de referência|r.", "-" },
    { "li", "|cffffd100Brilho de referência (nits)|r é o brilho do branco na cena. 203 é o valor padrão. Aumente-o se a imagem parecer escura demais em um ambiente claro. Intensidade HDR não tem efeito nesse modo.", "-" },
    { "p", "Se a imagem não mudar, clique em |cffffd100Reiniciar|r no rodapé." },
    { "h3", "Solução de problemas de HDR" },
    { "row", "Imagem muito escura", "Marque um dos dois modos de brilho." },
    { "row", "Imagem cinza ou desbotada", "Ative o HDR no Windows (passo 1) e no menu do monitor." },
    { "row", "HDR automático ligado no Windows", "Desative-o (passo 1)." },
    { "row", "Realces muito brilhantes ou achatados", "Defina o brilho de pico com o valor real do seu monitor (passo 2)." },
    { "row", "Você quer o HDR desligado", "Desmarque |cffffd100Saída HDR|r." },
    { "p", "Cada linha de HDR tem um botão Padrão que devolve o valor do jogo." },
    { "h2", "8. Comandos" },
    { "row", "|cffffd100/pano|r", "Abre ou fecha a janela" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Aplica uma predefinição" },
    { "row", "|cffffd100/pano undo|r", "Desfaz a última alteração" },
    { "row", "|cffffd100/pano redo|r", "Refaz a alteração que você acabou de desfazer" },
    { "row", "|cffffd100/pano reset|r", "Volta cada configuração e cada filtro ao padrão" },
    { "row", "|cffffd100/pano status|r", "Mostra no chat o lugar e o momento detectados e os filtros aplicados agora (durante uma transição, os valores de destino)" },
    { "row", "|cffffd100/pano apply|r", "Grava de novo as configurações mudadas no Panorama" },
    { "row", "|cffffd100/pano restart|r", "Reinicia o motor gráfico" },
    { "row", "|cffffd100/pano minimap|r", "Mostra ou oculta o botão do minimapa" },
    { "h2", "9. Redefinição" },
    { "li", "O botão |cffffd100Padrão|r de cada linha redefine essa configuração.", "-" },
    { "li", "O botão |cffffd100Padrões|r do menu Gráficos do jogo redefine apenas as configurações que esse menu gerencia, e o Panorama o acompanha. Use os botões Padrão em |cffffd100/pano|r para as outras e para os filtros.", "-" },
    { "li", "|cffffd100Redefinir tudo|r (rodapé, com confirmação) ou |cffffd100/pano reset|r: volta cada configuração alterada no Panorama e cada filtro ao padrão. |cffffd100Desfazer|r a cancela até |cffffd100/reload|r. A aba Ambiente e as zonas ajustadas também são redefinidas. Seus filtros da aba Meus filtros também são apagados.", "-" },
}
